import{_ as t,o as n,c as a,a0 as o}from"./chunks/framework.D4fUSYzX.js";const u=JSON.parse('{"title":"ADR 0065: The open ticket bands order by ticket number","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0065-the-open-ticket-bands-order-by-ticket-number.md","filePath":"adr/0065-the-open-ticket-bands-order-by-ticket-number.md"}'),r={name:"adr/0065-the-open-ticket-bands-order-by-ticket-number.md"};function i(s,e,d,h,c,l){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0065-the-open-ticket-bands-order-by-ticket-number" tabindex="-1">ADR 0065: The open ticket bands order by ticket number <a class="header-anchor" href="#adr-0065-the-open-ticket-bands-order-by-ticket-number" aria-label="Permalink to &quot;ADR 0065: The open ticket bands order by ticket number&quot;">​</a></h1><p>Status: accepted Date: 2026-09-29</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>ADR 0050 made the ticket list sort within its attention band by newest external update, then ticket identity. The external update time is a source fact: every refresh re-reads it, and both the source and the plane itself (its own label writes) can move it. Every refresh therefore re-sorts the open pile, and rows the operator never touched jump places.</p><p>The rank answers a different question in the two regimes of the list. In the live bands - awaiting, running, and handed-off - &quot;what moved most recently&quot; is what the operator watches: a turn that just settled, an agent that just started. In the open pile the rank answers &quot;what changed on the source&quot;, which is not the work queue: a ticket&#39;s number is the stable fact of the pile, and the pile is the queue of work the factory has not started.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>The band keeps its first rank, and the second rank follows the band&#39;s regime.</strong> The live bands (awaiting, running, handed-off) keep ADR 0050&#39;s rank: newest external update, then ticket identity. The open bands (open actionable, open not actionable) order by ticket number ascending: the lowest-numbered ticket - the one that has waited longest - stands at the top of the pile. A ticket whose external key names no number (a security advisory) stands after every numbered ticket in its band, and ties, and the no-number run, break by ticket identity.</p><p><strong>The one order stays one order.</strong> The flat list, the ignored pile, and the Group rank all read this same comparator (ADR 0059): the Group&#39;s second rank is the smallest second rank among the rows it holds - its newest external update in the live regime, its lowest ticket number in the open regime. The automatic top-up keeps taking its continuation and its next open ticket in the list&#39;s order (ADR 0050, ADR 0051), so the factory now starts its lowest-numbered eligible open ticket first. Oldest ticket first becomes the open dispatch policy, and the order the operator sees stays the order the factory acts in.</p><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>Keep the update order everywhere and give the display a stable copy.</strong> Two orders answering one question, the competition ADR 0050 retired, and the top-up would act on an order the operator no longer sees.</li><li><strong>Order the open bands by number descending.</strong> It reads &quot;what is new&quot;, but it puts the longest-waiting ticket at the bottom of the pile, and the top-up would start the newest ticket first.</li><li><strong>Order every band by number.</strong> It loses the recency the operator uses in the live bands to see what just moved.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>A row in the open pile no longer jumps on a refresh: a number never changes, and a new ticket enters at the bottom of the pile as its larger number. Rows still move when they cross a band, and that is the band design working as intended.</li><li>The auto top-up&#39;s open-ticket walk changes its pick when two open tickets compete: the lowest-numbered eligible ticket starts first, not the most-recently-updated one.</li><li>Group headers of open tickets stand by their lowest ticket number, not their newest update, where the two disagree.</li><li>The live bands are untouched: awaiting, running, and handed-off still put the most recently moved work first, and the top-up&#39;s continuation walk keeps the order it had.</li><li>A ticket without a number (a security advisory) stands last in its open band, in ticket identity order.</li></ul>',12)])])}const b=t(r,[["render",i]]);export{u as __pageData,b as default};
